INSERT INTO `products` (`id_product`, `id_category`, `name`, `price`, `description`, `isFlashSale`, `flash_sale_end_time`, `flash_sale_type`, `flash_sale_value`, `image`, `is_active`, `variants`) VALUES
	(1, 1, 'Gà Rán Truyền Thống', 35000, 'Đùi hoặc cánh gà tẩm bột chiên giòn rụm với lớp vỏ vàng óng, thịt bên trong mềm mọng nước, thơm ngon đậm vị.', 0, NULL, NULL, NULL, 'https://www.noichienkhongdau.com/wp-content/uploads/2021/08/dui-ga-chien-xu-bang-noi-chien-khong-dau-3.jpg', 1, '[{"name": "Vị Cay", "extraPrice": 0}, {"name": "Không Cay", "extraPrice": 0}, {"name": "Phủ Phô Mai", "extraPrice": 10000}, {"name": "Thêm Sốt Phô Mai Cay", "extraPrice": 12000}, {"name": "Đổi sang lườn gà", "extraPrice": 5000}]'),
	(2, 2, 'Burger Zinger', 55000, 'Burger gà giòn cay Zinger đặc trưng kết hợp cùng xốt Mayonnaise béo ngậy và rau xà lách tươi mát.', 0, NULL, NULL, NULL, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQuHStLzr2NGpCGj0F0EELGKaRp6jTLFcTVnaW3GUpoLC_I6aVkACQz-g4&s=10', 1, '[{"name": "Thêm phô mai lát", "extraPrice": 10000}, {"name": "Thêm thịt xông khói (Bacon)", "extraPrice": 15000}, {"name": "Không lấy salad", "extraPrice": 0}, {"name": "Thêm xốt Mayonnaise đặc biệt", "extraPrice": 5000}]'),
